// Bad: O(n²) allocations
string result = "";
for (int i = 0; i < 10000; i++) {
    result += i.ToString(); // New object each time!
}

// Good: O(n) with StringBuilder
var sb = new StringBuilder();
for (int i = 0; i < 10000; i++) {
    sb.Append(i); // Same buffer
}
string result = sb.ToString();

